import json
def solve(g):
    Hh,Ww=len(g),len(g[0])
    # sources: nonzero cells; group by (row source set, col source set)
    src_row={}  # row -> color (any nonzero in that row)
    src_col={}
    for i in range(Hh):
        for j in range(Ww):
            v=g[i][j]
            if v!=0:
                src_row[i]=v; src_col[j]=v
    o=[row[:] for row in g]
    # paint rows first, then columns override
    for i in range(Hh):
        if i in src_row:
            v=src_row[i]
            for j in range(Ww):
                if o[i][j]==0: o[i][j]=v
    for j in range(Ww):
        if j in src_col:
            v=src_col[j]
            for i in range(Hh):
                if o[i][j]==0: o[i][j]=v
    return o
