G=load()
def f(I):
    H,W=len(I),len(I[0])
    O=[r[:] for r in I]
    # singleton centers: colored cell, no same-color orthogonal neighbor (non-3 colors only)
    singles=[]
    for i in range(H):
        for j in range(W):
            c=I[i][j]
            if c==0 or c==3: continue
            n=sum(1 for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=i+dx<H and 0<=j+dy<W and I[i+dx][j+dy]==c)
            if n==0: singles.append((i,j,c))
    final=[r[:] for r in I]
    # row fills first, then column fills overwrite
    for i,j,c in singles:
        for k_ in range(W):
            if I[i][k_]==0: final[i][k_]=c
        for k_ in range(H):
            if I[k_][j]==0: final[k_][j]=c
    return final
