# Hypothesis: ray paints background (0) cells; stops at any non-background cell.
# Conflicts at crossings: test which wins.
def extents(grid):
    H=len(grid);W=len(grid[0])
    res=[row[:] for row in grid]
    casts=[]
    for i in range(H):
        for j in range(W):
            v=grid[i][j]
            if v not in (0,3):
                L=j>0 and grid[i][j-1]==3; R=j<W-1 and grid[i][j+1]==3
                U=i>0 and grid[i-1][j]==3; D=i<H-1 and grid[i+1][j]==3
                if L and R: casts.append(('h',i,v))
                elif U and D: casts.append(('v',j,v))
    # assign each background cell the color of the ray passing through it; crossings -> ?
    owns={}
    for typ,a,b in casts:
        if typ=='h':
            k=a
            for j in range(W):
                if grid[a][j]!=0: break
                if grid[a][j]==b: continue
                owns[(a,j)]=('h',b)
                k=j
            for j in range(a, -1, -1):
                if grid[a][j]!=0: break
                owns[(a,j)]=('h',b)
        else:
            k=a
            for i in range(H):
                if grid[i][a]!=0: break
                owns[(i,a)]=('v',b)
                k=i
            for i in range(a,-1,-1):
                if grid[i][a]!=0: break
                owns[(i,a)]=('v',b)
    return owns
